def get_unique(income):
    # Create an empty dictionary to store unique keys for each value
    unique_keys = {}

    # Loop over each item in the income tuple
    for element in income:
        if element in unique_keys:
            # If the element is already in the dictionary, increment its count
            unique_keys[element] += 1
        else:
            # If the element is not in the dictionary, add it with a count of 1
            unique_keys[element] = 1

    # Convert the dictionary keys and values to a string inside curly braces
    result = '{' + ', '.join(f'{key}: {value}' for key, value in unique_keys.items()) + '}'
    return result
