def find_triplet_array(arr, n, sum):
    arr.sort()  # Sort the array to use two-pointer technique
    for i in range(n-2):
        j = i + 1
        k = n - 1
        while j < k:
            if arr[i] + arr[j] + arr[k] == sum:
                return (arr[i], arr[j], arr[k])
            elif arr[i] + arr[j] + arr[k] < sum:
                j += 1
            else:
                k -= 1
    return None  # If no triplet is found that sums up to the given sum
