def maximum_segments(n, a, b, c):
    if b <= c:
        max_segments = a * n // (a + b)
    else:
        max_segments = a * n // (a + c)
    if a < b and b < c:
        result = max_segments + ((b - a) - (max_segments % (b - a))) % (b - a)
    elif a < b and b > c:
