def find_First_Missing(arr, start, end):
    # If the first element is not 0, the first missing number is 0
    if arr[start] != start:
        return start

    # If the last element is not the length of the array minus one, the first missing number is length of the array
    if arr[end] != end:
        return end + 1

    # Perform binary search
    while start <= end:
        mid = (start + end) // 2

        # If the element at the midpoint is equal to the midpoint, the first missing number is at or after the midpoint
        if arr[mid] == mid:
            start = mid + 1
        else:
