def find_Rotations(Str):
    # Check if the string is empty or single character, return 0 rotations
    if len(Str) <= 1:
        return 0

    # Count occurrences of the starting element
    str_len = len(Str)
    count = Str.count(Str[0])

    if str_len % count == 0:
        # Calculate the number of rotations equal to the string length
        return str_len // count
    else:
        # Calculate the minimum rotations needed
        min_rotations = str_len // count + 1
        for i in range(count):
            # If we find another starting point, adjust rotations
            if Str[i:str_len] == Str:
                min_rotations = min(min_rotations, i + 1)
        return min_rotations
