def set_Right_most_Unset_Bit(number):
    # Find the position of the rightmost unset bit
    position = 0
    while ((number >> position) & 1) == 1:
        position += 1

    # Set the rightmost unset bit by adding 2^position to the number
    return number | (1 << position)
