def super_seq(str1, str2, n1, n2):
    # Create a 2D DP table to store lengths of longest common subsequences
    dp = [[None for x in range(n2+1)] for x in range(n1+1)]

    # Fill dp table in bottom-up manner
    for i in range(n1+1):
        for j in range(n2+1):
            if i == 0:
                dp[i][j] = j
            elif j == 0:
                dp[i][j] = i
            elif str1[i-1] == str2[j-1]:
                dp[i][j] = 1 + dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1])

    # The length of the shortest supersequence is the sum of string lengths minus the length of LCS
    return n1 + n2 - dp[n1][n2]
