def max_sum_of_three_consecutive(arr, n):
    max_matrix = [[0 for _ in range(n)] for _ in range(n)]

    # Fill the first row
    for i in range(n): 
        max_matrix[0][i] = arr[i] 

    # Fill the first column
    for i in range(n): 
        max_matrix[i][0] = arr[i] 

    # Fill the first diagonal (top-left to bottom-right) 
    for i in range(1, n): 
        for j in range(1, n): 
            if i == j:
                max_matrix[i][j] = max_matrix[i-1][j-1] + arr[i] 
            else:
                max_matrix[i][j] = max(max_matrix[i-1][j], 
                                         max_matrix[i-1][j-1], 
                                         max_matrix[i][j-1]) + arr[i] 

    # Find the maximum sum from the last row
    return max(max_matrix[n-1])
