# Define the function to find the kth element from the sorted arrays
def find_kth(arr1, arr2, l1, l2, k):
    # Base case: if one of the arrays is empty, return the kth element from the other array
    if l1 == 0:
        return arr2[k - 1]
    if l2 == 0:
        return arr1[k - 1]
    # Calculate the middle index of both arrays
    mid1 = l1 // 2
    mid2 = l2 // 2
    # Compare the middle elements of both arrays
    if arr1[mid1] <= arr2[mid2]:
        # If the middle element of arr1 is less than or equal to the middle element of arr2, search in the right half of arr1
        return find_kth(arr1[mid1 + 1:], arr2, l1 - (mid1 + 1), l2, k - (mid1 + 1))
    else:
        # Otherwise, search in the left half of arr2
        return find_kth(arr1, arr2[:mid2], l1, l2 - (mid2 + 1), k)
