def find_kth(A, B, i, j, k):
    while i < len(A) and j < len(B):
        if k > 1:
            mid_A = A[(i + j) // 2]
            mid_B = B[(i + j) // 2]
            if mid_A <= mid_B:
                i += 1
            else:
                j += 1
                k -= 1
        else:
            return (min(A[i], B[j]), k)
    if i < len(A):
        return (A[i], k - i)
    return (B[j], k - j)
