def second_frequent(seq):
    # Count the frequency of each string
    freq = {}
    for str in seq:
        if str in freq:
            freq[str] += 1
        else:
            freq[str] = 1

    # Sort the frequencies in descending order and keep only the top two
    sorted_freq = sorted(freq.items(), key=lambda x: x[1], reverse=True)[:2]

    # Return the second most frequent string
    return sorted_freq[0][0] if len(sorted_freq) > 0 else None
