def find_triplet_array(arr, target, sum_val):
    arr.sort()  # Sort the array to make it easier to navigate
    n = len(arr)

    # Iterate through the array to find triplets
    for i in range(n-2):
        left = i + 1
        right = n - 1

        # Use two-pointer technique to find the triplet
        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]

            # If the sum of the current triplet is equal to the target
            if current_sum == sum_val:
                return (arr[i], arr[left], arr[right])

            # If the sum is less than the target, move the left pointer to the right
            elif current_sum < sum_val:
                left += 1

            # If the sum is greater than the target, move the right pointer to the left
            else:
                right -= 1

    # If no triplet with the sum equal to the target is found, return None
    return None
```

