            if j == 0:
                dp[i][j] = True
            elif j < array[i - 1]:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - array[i - 1]]

    max_taken_value = 0
    for i in range(len(array) + 1):
        if dp[-1][i]:
            max_taken_value = i

