from collections import deque

def max_height(root):
    if not root:
        return 0

    max_depth = 0
    queue = deque([root])

    while queue:
        level_size = len(queue)
        max_depth += 1

        for _ in range(level_size):
            node = queue.popleft()

            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)

    return max_depth
```

