    # If element at start is less than or equal to the element at middle,
    # then middle element is not necessarily the max, 
    # so check the left part
    elif a[start] <= a[mid]:
        return find_Max(a,start,mid - 1)

    # Else the max element is in the right part
    else:
        return find_Max(a,mid+1,ends)
