def dealnnoy_num(row, col):
    # Initialize a 2D array to store the delannoy numbers
    delannoy = [[0 for _ in range(col + 1)] for _ in range(row + 1)]

    # Initial conditions for the first row and column
    for j in range(col + 1):
        delannoy[0][j] = 1
    for i in range(row + 1):
        delannoy[i][0] = 1

    # Fill the rest of the matrix using the recurrence relation
    for i in range(1, row + 1):
        for j in range(1, col + 1):
            delannoy[i][j] = delannoy[i - 1][j] + delannoy[i][j - 1]

    # Return the nth delannoy number
    return delannoy[row][col]
