def dealnnoy_num(n, k):
    # Initialize the base case
    if n == 0:
        return 1 if k == 0 else 0
    if k == 0:
        return 1
    # Compute the Delannoy number using recursion
    if k > n:
        return 0
    if k == 1:
        return 2**n
    # Apply the recursive formula to compute the Delannoy number
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0], dp[1][0], dp[1][1] = 1, 1, 2
    for i in range(2, n + 1):
        for j in range(1, min(i, k) + 1):
            dp[i][j] = dp[i - 1][j] + dp[i - 1][j - 1]
    return dp[n][k]
```

