def min_coins(coins, m, V):
    def minCoinsRecursive(coins, m, V):
        # Base condition
        if V == 0:
            return 0
        if m == 0:
            return float("inf")
        # If current coin is larger than V, skip it
        if coins[m - 1] > V:
            return minCoinsRecursive(coins, m - 1, V)
        # Min of adding current coin or skipping it
        return min(1 + minCoinsRecursive(coins, m, V - coins[m - 1]), minCoinsRecursive(coins, m - 1, V))

    return minCoinsRecursive(coins, m, V)

