def min_coins(coins, total_value, memo=None):
    if memo is None:
        memo = {}
    if total_value == 0:
        return 0
    if total_value < 0:
        return float('inf')
    if total_value not in memo:
        min_coins_count = min([min_coins(coins, total_value - coin, memo) + 1 for coin in coins]) 
        memo[total_value] = min_coins_count if min_coins_count != float('inf') else 0
    return memo[total_value]
