def flatten_tuple(list_of_tuples):
    # Initialize an empty string to store the flattened result
    flat_str = ""
    # Iterate through each tuple in the list
    for tuple_tuple in list_of_tuples:
        # Iterate through each element in the tuple
        for element in tuple_tuple:
            # Append the element to the flattened string with a space
            flat_str += element + " "
    # Return the flattened string by removing the trailing space
    return flat_str.strip()
