def extract_even(mixed_tuple):
    def is_even(n):
        # Check if a number is even
        return n % 2 == 0

    def flat_tuple(t):
        # Flatten a nested tuple
        for item in t:
            if isinstance(item, tuple):
                yield from flat_tuple(item)
            else:
                yield item

    even_elements = [x for x in flat_tuple(mixed_tuple) if is_even(x)]
    return tuple(even_elements)
```

