def sum_Of_Primes(n):
    if n == 0 or n == 1:
        return 0
    primes = [True] * (n + 1)
    for p in range(2, int(n**0.5) + 1):
        if primes[p]:
            for i in range(p * p, n + 1, p):
                primes[i] = False
    return sum(p for p in range(2, n + 1) if primes[p])
