def sum_Of_product(n):
    sum = 0
    for i in range(1, n + 1):
        sum += i**(n - i) * binomial_coefficient(n, i)
    return sum

def binomial_coefficient(n, k):
    if k < 0 or k > n:
        return 0
    n_fact = 1
    k_fact = 1
    for i in range(1, n + 1):
        n_fact *= i
    for i in range(1, k + 1):
        k_fact *= i
    return n_fact // (k_fact * (n - k + 1))
```

