def get_Pairs_Count(arr, sum, count):
    # Using a dictionary to keep track of frequencies of elements
    num_freq = {}
    for num in arr:
        num_freq[num] = num_freq.get(num, 0) + 1

    for num in num_freq:
        complement = sum - num
        if complement in num_freq:
            # If complement exists and is not the same as the current num, increment count
            if complement != num:
                count += num_freq[complement] * num_freq[num]
            else:  # If complement is the same as the current num, increment count by the square of num_freq[num]
                count += (num_freq[num]) * (num_freq[num] - 1) // 2

    return count
