def max_sum_of_three_consecutive(arr, N):
    if N < 3:
        return 0

    # Boyer-Moore Voting Algorithm for finding the majority element
    candidate1 = candidate2 = None
    count1 = count2 = 0

    for num in arr:
        if candidate1 == num:
            count1 += 1
        elif candidate2 == num:
            count2 += 1
        elif count1 == 0:
            candidate1 = num
            count1 = 1
        elif count2 == 0:
            candidate2 = num
            count2 = 1
        else:
            count1 -= 1
            count2 -= 1

    # Verify that both candidates are actually the majority elements
    count1, count2 = 0, 0
    for num in arr:
        if candidate1 == num:
            count1 += 1
        elif candidate2 == num:
            count2 += 1

    # Choose the candidate with the maximum count
    if count1 > count2:
        majority_element = candidate1
    else:
        majority_element = candidate2

    # Find the maximum sum of the majority elements with no three consecutive elements
    max_sum = 0
    prev1, prev2 = arr[0], arr[1]
    for num in arr[2:]:
        max_sum = max(max_sum, num)
        if num != majority_element and prev1 != majority_element and prev2 != majority_element:
            prev1, prev2 = prev2, num
        else:
            prev1, prev2 = prev2, num

    return max_sum
