    if length < 3:
        return sum(nums)

    # Initialize prefix sums and DP array
    pre_sum = [0] * (length + 1)
    dp = [0] * (length + 1)

    # Fill prefix sums
    for i in range(1, length + 1):
        pre_sum[i] = pre_sum[i - 1] + nums[i - 1]

    # Fill DP array
    for i in range(1, length):
        dp[i] = pre_sum[i + 1] - pre_sum[i]

    # Find the maximum sum excluding consecutive elements
    max_sum = 0
    for i in range(1, length - 1):
        # Skip any three consecutive elements
        if i < length - 2:
            max_sum = max(max_sum, pre_sum[i] + dp[i] + dp[i + 1] - pre_sum[i + 4])

