import numpy as np

def Check_Solution(a, b, c):
    # Calculate the discriminant
    discriminant = b**2 - 4*a*c

    # Check if the discriminant is zero (when roots are real and equal)
    if discriminant == 0:
        # Check if both roots are zero
        if a == 0:
            return "Yes"
        else:
            return "No"
    elif discriminant < 0:
        return "No"
    else:
        root1 = (-b + np.sqrt(discriminant)) / (2*a)
        root2 = (-b - np.sqrt(discriminant)) / (2*a)

        # Check if the roots are numerically equal but opposite in sign
        if abs(root1 + root2) < 1e-6 and np.sign(root1) == -np.sign(root2):
            return "Yes"
        else:
            return "No"
