def rencontres_number(r, n):
    # Base case: the number of rencontres when one person is at position r
    if n == 1:
        return r
    # Recursive case: sum of rencontres where one person is at positions r and 1 to r-1
    return sum([rencontres_number(1, i) for i in range(1, r+1)]) + rencontres_number(r-1, n-1)
