def rencontres_number(n, k):
    # Function to calculate the binomial coefficient
    def binomial_coefficient(n, k):
        if k > n - k:
            k = n - k
        result = 1
        for i in range(1, k + 1):
            result *= (n - i + 1) / i
        return int(result)

    # Calculate the n-th rencontres number
    rencontres = binomial_coefficient(n * (n + 1) // 2 + k - 1, k)
    return rencontres
```

