def min_cost(cost, m, n):
    # Initialize the DP table with a large value, then set the starting point to 0
    path_table = [[float('inf')] * (n + 1) for _ in range(m + 1)]
    path_table[0][0] = cost[0][0]

    # Use dynamic programming to calculate the minimum cost
    for i in range(1, m + 1):
        path_table[i][0] = path_table[i - 1][0] + cost[i][0]
    for j in range(1, n + 1):
        path_table[0][j] = path_table[0][j - 1] + cost[0][j]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            path_table[i][j] = min(path_table[i - 1][j], path_table[i][j - 1], path_table[i - 1][j - 1]) + cost[i][j]

    return path_table[m][n]
```

