def rencontres_number(n, k):
    if n < 1 or k < 0:
        return "Invalid input"
    if k > n // 2:
        k = n - k

    def binomial_coefficient(n, k):
        if k == 0 or k == n:
            return 1
        if k > n // 2:
            k = n - k
        res = 1
        for i in range(k):
            res *= (n - i)
            res //= (i + 1)
        return res

    return binomial_coefficient(n + k - 1, k) - binomial_coefficient(n - 1, k)
