def rencontres_number(n, k):
    # Base case: if k is 0 or n == k, the result is 1
    if k == 0 or n == k:
        return 1
    # Recursive case: nCr = (n - 1) choose (k - 1) * n choose k
    return (n - 1) * int(recontres_number(n - 1, k - 1)) + (n - 1) * int(recontres_number(n, k))
