def rencontres_number(n, k):
    #Helper function to calculate factorial
    def factorial(num):
        result = 1
        for i in range(2, num + 1):
            result *= i
        return result

    #Base cases
    if n == k:
        return n
    if n == 1 or k == 0:
        return 1

    #Recursive case
    return (factorial(n) / (factorial(k) * factorial(n - k)) * (k + 1) ** (n - 1))
```

