def join_tuples(tupleList):
    # Initialize an empty dictionary to store tuples based on their initial elements
    dict_result = {}

    for item in tupleList:
        # Check if the first element of the tuple exists in the dictionary
        if item[0] in dict_result:
            # Append the tuple to the list associated with the first element
            dict_result[item[0]].append(item)
        else:
            # Create a new list for the first element and add the tuple to it
            dict_result[item[0]] = [item]

    # Return the dictionary, which now contains the combined tuples
    return tuple(sorted(value) for key, value in dict_result.items())
