    if high < low:
        return arr[low]

    # Finding the middle element
    mid = low + (high - low) // 2

    # If the middle element is greater than the next element, it means the max element is in the left half
    if arr[mid] > arr[mid + 1]:
        return find_Max(arr, low, mid)

    # If the middle element is less than the previous element, it means the max element is in the right half
    if arr[mid - 1] > arr[mid]:
