def find_Max(nums, l, h):    
    if l > h:
        return -1  # In case the array is empty or not rotated

    if l == h:
        return nums[l]

    mid = (l + h) // 2

    # Check if the array is rotated at mid
    if nums[mid] > nums[mid + 1]:
        return nums[mid]

    # Left half is sorted
    if nums[l] <= nums[mid]:
        return find_Max(nums, l, mid - 1)

    # Right half is sorted
    return find_Max(nums, mid + 1, h)
