def min_coins(coins, value, n): 
    # Table to store results of subproblems 
    table = [[0 for i in range(value + 1)] for i in range(n + 1)] 

    # Build table in bottom up manner 
    for i in range(n + 1): 
        for j in range(value + 1): 

            # If value is 0, then we need 0 coins to make it
            if (j == 0): table[i][j] = 0
            # If value is greater than or equal to coin denomination, we can get it by using coin or excluding it
            elif (j >= coins[i - 1]): 
                table[i][j] = min( 1 + table[i][j - coins[i - 1]] , table[i - 1][j]) 
            else: 
                table[i][j] = table[i - 1][j] 

    return table[n][value] 
```

