def min_coins(coins, n, sum):
    # create a list to store the minimum number of coins necessary for each sum up to/ including sum
    dp = [0]*(sum+1)

    # Iterate over each coin denomination
    for i in range(1, n+1):
        # Update the DP table values for the possible sums
        for j in range(coins[i-1], sum+1):
            if dp[j-coins[i-1]] != -1:
                dp[j]=min(dp[j], dp[j-coins[i-1]]+1)

    # If it's not possible to make the required sum
    if dp[sum] == -1:
        return -1

    return dp[sum]
