def min_coins(coins, value, total):
    # Initialize a 2D list to store the minimum coins required for each value
    dp = [[float('inf')] * (total + 1) for _ in range(len(coins) + 1)]

    # Base case: to make 0 value, no coins are required
    dp[0][0] = 0

    # Fill the dp table
    for i in range(1, len(coins) + 1):
        for j in range(total + 1):
            if j - coins[i - 1] < 0:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = min(dp[i - 1][j], dp[i][j - coins[i - 1]] + 1)

    # If the result is still infinity, it means the value is not achievable
    if dp[-1][-1] == float('inf'):
        return -1
    else:
        return dp[-1][-1]
