def min_coins(coins, n, total):
    table = [[float('inf')] * (total + 1) for _ in range(n + 1)]
    table[0][0] = 0

    for i in range(1, n + 1):
        for j in range(total + 1):
            if j < coins[i - 1]:
                table[i][j] = table[i - 1][j]
            else:
                table[i][j] = min(table[i - 1][j], 1 + table[i][j - coins[i - 1]])

    return table[n][total]
