def find_fixed_point(arr):
    low, high = 0, len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == mid:
            return mid
        elif arr[mid] > mid:
            high = mid - 1
        else:
            low = mid + 1
    return -1
