def set_Right_most_Unset_Bit(n):
    # Find the position of the rightmost unset bit
    if n == 0:
        return 1  # 1 is the rightmost unset bit in binary representation

    while n & (n - 1):
        n &= (n - 1)  # Unset the rightmost unset bit

    # Return n + 1 as n is landlord and the new rightmost unset bit will be at n + 1
    return n + 1
