def sum_of_square(n):
    def binomial_coefficient(n, k):
        # Utilize Pascal's triangle formula for binomial coefficient
        return factorial(n) // (factorial(k) * factorial(n - k))

    # Calculate sum of squares of binomial coefficients
    sum_val = sum(binomial_coefficient(n, k) ** 2 for k in range(n + 1))

    return sum_val

