def get_Number(n, k):
    # Initialize two counters: one to keep track of odd numbers and another for even numbers
    odd_count, even_count = 0, 0
    # Initialize the array to store the kth odd and even numbers
    result = []

    # Loop through all possible elements from 1 to n
    for i in range(n):
        # Check if the current number is odd
        if i % 2 != 0:
            if odd_count == k - 1:
                result.append(i)
                odd_count += 1
            else:
                odd_count += 1
        # Check if the current number is even
        else:
            if even_count == k - 1:
                result.append(i)
                even_count += 1
            else:
                even_count += 1

    # Return the kth element if it exists
    if k <= len(result):
        return result[k - 1]
    else:
        return None
