def count_Rotation(arr, n):
    def is_sorted(arr, size):
        for i in range(size - 1):
            if arr[i] > arr[i + 1]:
                return False
        return True

    start, end = 0, n - 1

    while start < end:
        mid = (start + end) // 2

        if arr[mid] < arr[end]:
            end = mid
        else:
            start = mid + 1

    return start if is_sorted(arr, start) else start + 1
