def find_closet(arr1, arr2, arr3, n1, n2, n3):
    i = 0
    j = 0
    k = 0
    min_diff = float('inf')
    closest_elements = (0, 0, 0)

    while i < n1 and j < n2 and k < n3:
        diff1 = min(abs(arr1[i] - arr2[j]), abs(arr1[i] - arr3[k]))
        diff2 = min(abs(arr2[j] - arr3[k]), abs(arr2[j] - arr1[i]))
        diff3 = min(abs(arr3[k] - arr1[i]), abs(arr3[k] - arr2[j]))
        min_diff = min(min_diff, diff1, diff2, diff3)

        if min_diff == diff1:
            closest_elements = (arr1[i], arr2[j], arr3[k])
        elif min_diff == diff2:
            closest_elements = (arr2[j], arr1[i], arr3[k])
        elif min_diff == diff3:
            closest_elements = (arr3[k], arr1[i], arr2[j])

        if min_diff == abs(arr1[i] - arr2[j]):
            i += 1
        elif min_diff == abs(arr2[j] - arr3[k]):
            j += 1
        else:
            k += 1

    return closest_elements
