def find_closet(arr1, arr2, arr3, m, n, p):
    dp = [[float('inf')] * (p + 1) for _ in range(min(m, n))]
    ans = [float('inf')] * (p + 1)

    for i in range(1, min(m, n) + 1):
        for j in range(1, p + 1):
            k = min(p, n - i + 1)
            while (j > 1) and (dp[i - 1][j - 1] < dp[i][j]):
                j -= 1
            while (k > 0) and (dp[i - 1][j] + dp[i - 1][k - i + 1] < dp[i][j]):
                k -= 1
            dp[i][j] += min(dp[i - 1][j - 1], dp[i - 1][j] + dp[i - 1][k - i + 1])
            if dp[i][j] < ans[j]:
                ans[j] = dp[i][j]

    closest_elements = [arr1[i - 1] if i % m == 0 else arr2[i - m - 1] if i % n == 0 else arr3[min(m, n) - (i - (i // m) * m - 1) - 1] for i in range(1, p + 1)]
    return closest_elements
