def super_seq(str1, str2, l1, l2):
    dp = [[0] * (l2 + 1) for _ in range(l1 + 1)]

    for i in range(1, l1 + 1):
        for j in range(1, l2 + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # The length of the longest common subsequence is in dp[l1][l2]
    # The length of the supersequence is the sum of the lengths of the longest common subsequence
    # and the individual string lengths minus the length of the LCS to avoid double counting
    return dp[l1][l2] + l1 + l2 - dp[l1][l2]
