                dp[i][j] = j 
            elif j == 0: 
                dp[i][j] = i 
            elif str1[i-1] == str2[j-1]: 
                dp[i][j] = dp[i-1][j-1] + 1
            else: 
                dp[i][j] = 1 + min(dp[i][j-1], dp[i-1][j])

