def last(arr, low, high):
    # Ensure low less than high
    if low > high:
        return -1

    # Calculate the middle index
    mid = (low + high) // 2

    # If the element is at the middle or the element before the middle
    # is not equal to the middle, return the middle
    if (mid == 0 or arr[mid - 1] != arr[mid]) and arr[mid] == arr[high]:
        return mid

    # If the element is greater than or equal to the middle, search in the right half
    elif arr[mid] >= arr[high]:
        return last(arr, mid + 1, high)

    # Otherwise, search in the left half
    else:
        return last(arr, low, mid - 1)
