import math

def lobb_num(n, m):
    last_digit = n % 10
    prep = int(math.ceil(last_digit / 10)) - 1
    if last_digit == 0 or prep == -1:
        return 0
    if last_digit == 1:
        return n - 1

    if last_digit == 9:
        return n

    for k in range(1, prep + 1):
        excepted = last_digit + 10 * k - 9 * k + 9 * 2 * k - 8 * k**2 + 7 * k**3
        if excepted <= n:
            res = n - excepted
        else:
            res = n - (last_digit + 10 * k - 9 * k + 9 * 2 * k - 8 * k**2 + 7 * k**3)
            k -= 1
            break
    return res
