def dealnnoy_num(n, row):
    # Initialize the 2D array to store the values of dealnoy numbers
    dp = [[0 for _ in range(row + 1)] for _ in range(n + 1)]

    # Base cases
    dp[0][0] = 1

    # Fill the dp array
    for i in range(1, n + 1):
        for j in range(row + 1):
            if i + j == 0:
                dp[i][j] = 1
            elif j > 0 and i > 0:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1] + dp[i - 1][j - 1]

    return dp[n][row]
