    if n == 0:
        return 1

    # Collections list for storing bell numbers
    bell = [0] * (n + 1)
    bell[0] = 1

    # Calculate bell numbers using the recursive relation
    for i in range(1, n + 1):
        for j in range(i):
            bell[i] += bell[j] * factorial(i - j - 1)

