def count_Fac(num):
    # Initialize a list to count the power of each prime factor
    prime_count = [0] * 10  # We assume that prime factors are up to 10

    # Divide num by 2 to remove all even factors
    while num % 2 == 0:
        prime_count[0] += 1
        num //= 2

    # Now num must be an odd number
    for i in range(3, int(num**0.5) + 1, 2):
        # While i divides num, increment its count
        while num % i == 0:
            prime_count[i] += 1
            num //= i

    # If num is a prime number greater than 2
    if num > 2:
        prime_count[num] += 1

    # Calculate the total number of distinct power of prime factors
    return sum(1 for count in prime_count if count > 0)
