def count_duplic(lst):
    # Create an empty dictionary to store the frequency of each element
    freq_dict = {}
    # Create two empty lists to store the result
    unique_list = []
    duplicate_list = []

    # Count the frequency of each element in the list
    for num in lst:
        if num in freq_dict:
            freq_dict[num] += 1
        else:
            freq_dict[num] = 1

    # Find the unique elements and their frequencies
    for num, freq in freq_dict.items():
        if freq == 1:
            unique_list.append(num)
        else:
            duplicate_list.append((num, freq))

    # Sort the list of duplicates by frequency in descending order
    duplicate_list.sort(key=lambda x: x[1], reverse=True)

    return (unique_list, duplicate_list)
