def coin_change(coins, amount, count):
    def dfs(start):
        nonlocal amount, count, coins
        if amount == 0:
            return count
        if start == len(coins) or amount < 0:
            return 0
        # Include the current coin
        include_count = dfs(start + 1)
        # Exclude the current coin
        exclude_count = dfs(start + 1)
        return include_count + exclude_count

    return dfs(0)
