def coin_change(coins, amount, n):
    # If the amount is 0, there is only 1 way to make it (no coins needed)
    if amount == 0:
        return 1
    # If the amount is less than 0 or if we have explored all possible coins and couldn't reach the amount
    if amount < 0 or n == 0:
        return 0

    # We have two choices: either include the current coin or exclude it
    # Recursive call for including the current coin (amount - coins[n-1])
    # Recursive call for excluding the current coin (n-1)
    return coin_change(coins, amount - coins[n-1], n) + coin_change(coins, amount, n-1)
