from collections import deque

def find_Min_Swaps(binary_array, n):
    res = 0
    queue = deque()

    for i in range(n):
        queue.append(i)

    while queue:
        rot_len = len(queue)
        for i in range(rot_len):
            idx = queue.popleft()
            if 0 <= idx - 1 < n and binary_array[idx - 1] == 1:
                queue.append(idx - 1)
                res += 1
            if 0 <= idx + 1 < n and binary_array[idx + 1] == 1:
                queue.append(idx + 1)
                res += 1

    return res
```

