import math

def dealnnoy_num(a, b):
    # Calculate the binomial coefficient
    dp = [[0 for _ in range(b + 1)] for _ in range(a + 1)]
    for i in range(a + 1):
        dp[i][0] = dp[i][1] = 1
    for i in range(2, a + 1):
        for j in range(2, b + 1):
            dp[i][j] = dp[i-1][j] + dp[i][j-1]
    # Return the (a-1)th binomial coefficient
    return dp[a-1][b]
