def dealnnoy_num(n, k):
    if n == 0 or k == 0 or k == n:
        return 1
    if n > k:
        n, k = k, n
    result = 0
    for i in range(n + 1):
        result += binomial_coefficient(n, i) * binomial_coefficient(n - i, k - i)
    return result

def binomial_coefficient(n, k):
    if k > n - k:
        k = n - k
    result = 1
    for i in range(k):
        result *= (n - i)
        result //= (i + 1)
    return result
