def dealnnoy_num(n, k):
    def binom(n, k):
        if k > n // 2:
            return binom(n, n - k)
        res = 1
        for i in range(1, k + 1):
            res *= (n - k + i)
            res //= i
        return res

    def deln(n, k, m):
        if n == 0 or k == m:
            return 1
        return deln(n, k - 1, m) + deln(n - 1, k, m) + deln(n - 2, k - 1, m) + deln(n - 2, k, m - 1)

    return binom(n + k - 1, k - 1) * deln(n, k - 1, n - k) // binom(k + 1, 1)
```

