def get_Pairs_Count(arr, target, pair_size):
    arr.sort()  # Sorting the array
    count = 0
    low, high = 0, len(arr) - 1

    while low < high:
        current_sum = arr[low] + arr[high]
        if current_sum < target:
            low += 1
        elif current_sum > target:
            high -= 1
        else:
            if (high - low) >= pair_size:
                count += (high - low + 1) * (high - low) // 2
                low += 1
                high -= 1
            else:
                low += 1
                high -= 1

    return count
