    i, count = 2, 1
    while i <= math.sqrt(n):
        if n % i == 0:
            n //= i
            if i % 2 == 0:
                count += 1
            while n % i == 0:
                count += 1
                n //= i
        i += 1
    if n > 1:
        count += 1
    return count
```

