def largest_prime(n):
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
    # If n is a prime number greater than 2
    if n > 2:
        return n
    return i

def count_Fac(n):
    if n <= 1:
        return 0
    prime_factor = largest_prime(n)
    res = 1
    while prime_factor:
        res += 1
        n //= prime_factor
        prime_factor = largest_prime(n)
    return res
```

