def max_sum_of_three_consecutive(nums, n):
    if n < 3:
        return sum(nums)
    dp = [0] * n
    for i in range(n):
        if i < 2:
            dp[i] = nums[i]
        elif i == 2:
            dp[i] = nums[i] + nums[i-1]
        else:
            dp[i] = max(nums[i] + dp[i-3], dp[i-2])
    return max(dp)
```

