def bell_Number(n):
    if n == 0:
        return 1
    elif n == 1:
        return 1
    else:
        b = [0] * (n + 1)
        b[0], b[1] = 1, 1
        for i in range(2, n + 1):
            b[i] = sum(b[j - 1] for j in range(1, i + 1))
        return b[n]
