def bell_Number(n):
    bell = [0] * (n + 1)
    bell[0] = 1
    for i in range(1, n + 1):
        bell[i] = sum(bell[j] for j in range(i)) + (
            bell[i - 1] if i != 1 else 0
        )
    return bell[n]
```

