def floor_Max(n, m, p):
    # Calculate the greatest prime divisor less than n
    def greatest_prime(n):
        i = 2
        while n % i == 0:
            n //= i
        i = 3
        while i * i <= n:
            while n % i == 0:
                n //= i
            i += 2
        if n > 2:
            n //= i
        return n

    # Check the prime divisors of n, m, and p
    d0 = greatest_prime(n)
    d1 = greatest_prime(m)
    d2 = greatest_prime(p)

    # Return the minimum of the prime divisors for the maximum possible value
    return min(d0, d1, d2)
```

