def is_nonagonal(n):
    # Nonagonal number formula is given by (5*n^2 - 4*n) / 2
    # Solving for n, we get the quadratic formula (5*n^2 - 4*n) / 2 - N = 0 to find the nth term
    # n = (1 + sqrt(16 + 40*(N-1)) / 10
    import math
    # Solving the quadratic equation for real solutions
    discriminant = 16 + 40*(n-1)
    if discriminant < 0:
        return None  # In case of complex roots, return None
    roots = [(1 + math.sqrt(discriminant)) / 10, (1 - math.sqrt(discriminant)) / 10]
    for root in roots:
        if root.is_integer():
            return int(root)
    return None
```

