def min_Swaps(str1, str2):
    # Count of mismatches
    mismatch = 0
    # Index of mismatch
    index = -1
    # Number of required swaps
    swap_count = 0

    for i in range(len(str1)):
        if str1[i] != str2[i]:
            mismatch += 1
            if index == -1:
                index = i

    if mismatch == 1:
        return 0
    elif mismatch == 2:
        if str1[index] != str2[index + 1] and str1[index + 1] != str2[index] and str1[index] != str2[index - 1] and str1[index - 1] != str2[index]:
            return 1
        else:
            return 2
    elif mismatch == 3:
        # Find the first and second mismatch
        first_mismatch = index
        second_mismatch = -1
        for i in range(index + 1, len(str1)):
            if str1[i] != str2[i]:
                second_mismatch = i
                break

        swap_count = 1
        if int(str1[first_mismatch + 1:]) > int(str1[:second_mismatch]):
            swap_count += 1

    return swap_count
```

