import re

def num_position(s):
    nums = [str(num) for num in range(10)]
    position_keys = [str(i) for i in range(1, 10)]
    result = {}
    for key in position_keys:
        if key in s:
            match = re.search(f'(?=({key}[^0-9]{nums}[^0-9]{key}))(.*(?=({key}[^0-9]{nums}[^0-9]{key})))', s)
            if match:
                result[key] = (match.group(1), match.group(2)[:-len(key)])
    return sum([len(num) for num in result.values()]) if result else 0
