def maximum_segments(n, a, b, c):
    for i in range(n):
        # Check if n can be divided by each segment length
        if n % a == 0 and n % b == 0 and n % c == 0:
            return 3
        # Try to remove one segment at a time
        elif n % (a + b) == 0 or n % (a + c) == 0 or n % (b + c) == 0:
            return 2
        else:
            n -= 1
    return 0  # No segments can be formed
```

