def min_cost(cost, m, n):
    # Start from the bottom-right corner and move towards the top-left corner
    for i in range(m-1, -1, -1):
        for j in range(n-1, -1, -1):
            # Update the cost to reach the current cell by adding the minimum cost to reach the cell above or to the left
            if j > 0:
                cost[i][j] += min(cost[i][j+1], cost[i+1][j])
            else:
                cost[i][j] += cost[i+1][j]
            if i > 0:
                cost[i][j] += min(cost[i][j+1], cost[i-1][j])
            else:
                cost[i][j] += cost[i][j+1]

    # The minimum cost to reach (m, n) is the top-left value in the cost matrix
    return cost[0][0]
