def min_Swaps(str1, str2):
    if len(str1) != len(str2):
        return -1

    l = len(str1)
    swap = 0
    i = 0

    while i < l:
        while str1[i] == str2[i]:
            i += 1
        j = i + 1
        while j < l and str1[j] != str2[i]:
            j += 1

        if j == l:
