def find_kth(arr1, arr2, n1, n2, k):
    if n1 >= n2:
        return arr2[k - 1]
    if n2 >= n1:
        return arr1[k - 1]

    if k == 1:
        return min(arr1[0], arr2[0])

    mid1 = n1 // 2
    mid2 = n2 // 2
    median1 = arr1[mid1] if mid1 < n1 else float('inf')
    median2 = arr2[mid2] if mid2 < n2 else float('inf')

    if k <= mid1 + mid2:
        if median1 <= median2:
            return find_kth(arr1, arr2[:mid2], n1, mid2, k)
        else:
            return find_kth(arr1[:mid1], arr2, mid1, n2, k - mid1)
    else:
        if median1 <= median2:
            return find_kth(arr1[mid1 + 1:], arr2, n1 - mid1 - 1, n2, k - mid1 - 1)
        else:
            return find_kth(arr1, arr2[mid2 + 1:], n1, n2 - mid2 - 1, k - mid2 - 1)
