def set_Right_most_Unset_Bit(n):
    # If 'n' is zero, return 1 as no unset bit
    if n == 0:
        return 1
    # Rightmost unset bit is the bitwise right shift of 'n' by 1
    n = n + (n >> 1)
    return n | (1 << (n.bit_length() - 1))
