def super_seq(str1, str2, m, n):
    # Create an m+1 x n+1 matrix and fill with zeros
    dp = [[0] * (n+1) for _ in range(m+1)]

    # Fill the dp matrix
    for i in range(1, m+1):
        for j in range(1, n+1):
            if str1[i-1] == str2[j-1]:
                dp[i][j] = 1 + dp[i-1][j-1]
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    # The length of the longest common subsequence is dp[m][n]
    # Since we need the length of the shortest supersequence, we add m and n minus the
    # length of the最长 common subsequence
    return m + n - dp[m][n]
