def super_seq(str1, str2, m, n):
    # Create a 2D array to store lengths of LCSs
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Build the LCS table in bottom-up manner
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            elif str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # The length of the longest common subsequence
    longest_common_subsequence_length = dp[m][n]

    # The length of the supersequence is the sum of lengths of str1 and str2 
    # minus the length of their longest common subsequence
    return m + n - longest_common_subsequence_length
