def unique_sublists(lst):
    # Create an empty dictionary to store unique lists and their counts
    counts = {}
    for sublist in lst:
        # Convert the sublist to a tuple since dictionaries cannot contain mutable types as keys
        sublist_tuple = tuple(sublist)
        # If the sublist is already in the dictionary, increment its count; otherwise, add it to the dictionary
        if sublist_tuple in counts:
            counts[sublist_tuple] += 1
        else:
            counts[sublist_tuple] = 1
    # Filter out the lists with a count of 1 to leave only unique lists
    unique_counts = { sublist: count for sublist, count in counts.items() if count > 1 }
    return unique_counts
