def Total_Hamming_Distance(n):
    total_distance = 0
    max_base = n.bit_length()
    for base in range(1, max_base + 1):
        alternating_numbers = []
        for i in range(base, n + 1, base):
            alternating_numbers.append(i^(i+base))
        for i in range(base + 1, max_base + 1):
            for j in range(base, n + 1, base):
                group_numbers = alternating_numbers + [j^(j+base)]
                for num in group_numbers:
                    binary_representation = bin(num)[2:].zfill(max_base)
                    Hamming_distance = sum(1 for bit in binary_representation if bit == '1')
                    total_distance += Hamming_distance
    return total_distance
