import math

def coin_change(coins, value, change):
    dp = [[0]*(change+1) for _ in range(len(coins)+1)]

    for i in range(len(coins)+1):
        for j in range(change+1):
            if i == 0:
                dp[i][j] = 0
            elif j == 0:
                dp[i][j] = 1
            elif coins[i-1] <= j:
                dp[i][j] = dp[i-1][j] + dp[i][j-coins[i-1]]
            else:
                dp[i][j] = dp[i-1][j]

    return dp[len(coins)][change]
